/* 自动备份插件：监听 save 事件，节流后把全书写入 data/backups/ 滚动备份。
 * 文件操作统一走 ctx.electronAPI.pluginFs（主进程沙箱，限定在 data 目录内）。
 * 设置区：可调保留份数（默认 20）与最小间隔（默认 5 分钟），列出全部备份可逐份恢复。 */
(function () {
  'use strict';
  const DEF_KEEP = 20;
  const DEF_INTERVAL = 5 * 60 * 1000;

  window.MoyePlugins.register({
    id: 'auto-backup',
    name: '自动备份',
    activate(ctx) {
      this._ctx = ctx;
      this._last = 0;
      this._onSave = () => this.maybeBackup();
      ctx.on('save', this._onSave);

      const keep = ctx.getSetting('autoBackupKeep', DEF_KEEP);
      const interval = ctx.getSetting('autoBackupInterval', DEF_INTERVAL);

      ctx.ui.addSettingsSection({
        title: '自动备份（全书快照）',
        render: (c) => {
          const tip = document.createElement('p');
          tip.className = 'muted';
          tip.style.cssText = 'font-size:12px;line-height:1.6;margin:0 0 8px';
          tip.textContent = '保存后自动滚动备份到 data/backups/。';
          c.appendChild(tip);

          const optRow = document.createElement('div');
          optRow.className = 'tool-row';
          optRow.style.marginBottom = '8px';
          optRow.innerHTML =
            '<label class="set-check">保留 <input type="number" id="abKeep" min="1" max="200" value="' + keep + '" style="width:56px"> 份</label>' +
            '<label class="set-check">最小间隔 <input type="number" id="abInt" min="1" max="120" value="' + Math.round(interval / 60000) + '" style="width:48px"> 分</label>';
          c.appendChild(optRow);
          const keepInput = optRow.querySelector('#abKeep');
          const intInput = optRow.querySelector('#abInt');
          keepInput.addEventListener('change', () => ctx.setSetting('autoBackupKeep', Math.max(1, parseInt(keepInput.value) || DEF_KEEP)));
          intInput.addEventListener('change', () => ctx.setSetting('autoBackupInterval', Math.max(1, parseInt(intInput.value) || 5) * 60000));

          const row = document.createElement('div');
          row.className = 'tool-row';
          row.style.marginBottom = '10px';
          const backupNow = document.createElement('button');
          backupNow.className = 'mini-btn primary';
          backupNow.textContent = '立即备份';
          backupNow.addEventListener('click', () => this.backupNow(true));
          const restore = document.createElement('button');
          restore.className = 'mini-btn';
          restore.textContent = '恢复最近一份';
          restore.addEventListener('click', () => this.restoreLatest());
          row.appendChild(backupNow);
          row.appendChild(restore);
          c.appendChild(row);

          const listTitle = document.createElement('div');
          listTitle.className = 'muted';
          listTitle.style.cssText = 'font-size:12px;margin-bottom:4px';
          listTitle.textContent = '可恢复备份（点击恢复该份）';
          c.appendChild(listTitle);

          const list = document.createElement('div');
          list.id = 'abList';
          list.style.cssText = 'max-height:180px;overflow:auto';
          c.appendChild(list);
          this._listEl = list;
          this.renderList();
        }
      });
    },

    async renderList() {
      const ctx = this._ctx, list = this._listEl;
      if (!list) return;
      list.innerHTML = '<div class="muted" style="font-size:12px">读取中…</div>';
      try {
        const r = await ctx.electronAPI.pluginFs({ op: 'list', rel: 'backups' });
        if (!r || !r.ok) { list.innerHTML = '<div class="muted" style="font-size:12px">读取失败</div>'; return; }
        const files = r.items.filter((n) => /^novels-.*\.json$/.test(n)).sort().reverse();
        if (!files.length) { list.innerHTML = '<div class="muted" style="font-size:12px">还没有备份</div>'; return; }
        list.innerHTML = '';
        files.slice(0, 50).forEach((f) => {
          const item = document.createElement('div');
          item.className = 'tool-row';
          item.style.cssText = 'justify-content:space-between;padding:4px 0;border-bottom:1px solid var(--line)';
          const label = document.createElement('span');
          label.style.cssText = 'font-size:12px';
          label.textContent = f.replace(/^novels-/, '').replace(/\.json$/, '').replace(/-/g, ':');
          const btn = document.createElement('button');
          btn.className = 'mini-btn';
          btn.textContent = '恢复';
          btn.addEventListener('click', () => this.restoreFile(f));
          item.appendChild(label);
          item.appendChild(btn);
          list.appendChild(item);
        });
      } catch (e) {
        list.innerHTML = '<div class="muted" style="font-size:12px">读取失败</div>';
      }
    },

    getKeep() { return Math.max(1, this._ctx.getSetting('autoBackupKeep', DEF_KEEP)); },
    getInterval() { return Math.max(1, this._ctx.getSetting('autoBackupInterval', DEF_INTERVAL)); },

    maybeBackup() {
      const now = Date.now();
      if (now - this._last < this.getInterval()) return;
      this.backupNow(false);
    },

    async backupNow(manual) {
      const ctx = this._ctx;
      try {
        const db = ctx.getDb();
        const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
        const rel = 'backups/novels-' + stamp + '.json';
        const r = await ctx.electronAPI.pluginFs({ op: 'write', rel, content: JSON.stringify(db, null, 2) });
        if (!r || !r.ok) { if (manual) ctx.toast('备份失败：' + (r && r.error)); return; }
        this._last = Date.now();
        await this.prune();
        if (manual) { ctx.toast('已备份全书'); this.renderList(); }
      } catch (e) {
        console.error('[自动备份]', e);
        if (manual) ctx.toast('备份失败');
      }
    },

    async prune() {
      const ctx = this._ctx;
      try {
        const r = await ctx.electronAPI.pluginFs({ op: 'list', rel: 'backups' });
        if (!r || !r.ok) return;
        const files = r.items.filter((n) => /^novels-.*\.json$/.test(n)).sort();
        const keep = this.getKeep();
        while (files.length > keep) {
          const old = files.shift();
          await ctx.electronAPI.pluginFs({ op: 'delete', rel: 'backups/' + old });
        }
      } catch (e) { console.error('[自动备份] 清理', e); }
    },

    async restoreFile(f) {
      const ctx = this._ctx;
      try {
        const rd = await ctx.electronAPI.pluginFs({ op: 'read', rel: 'backups/' + f });
        if (!rd || !rd.ok) { ctx.toast('读取失败'); return; }
        ctx.replaceDb(JSON.parse(rd.content));
        ctx.toast('已恢复：' + f);
        this.renderList();
      } catch (e) {
        console.error('[自动备份] 恢复', e);
        ctx.toast('恢复失败');
      }
    },

    async restoreLatest() {
      const ctx = this._ctx;
      try {
        const r = await ctx.electronAPI.pluginFs({ op: 'list', rel: 'backups' });
        if (!r || !r.ok) { ctx.toast('读取备份失败'); return; }
        const files = r.items.filter((n) => /^novels-.*\.json$/.test(n)).sort();
        if (!files.length) { ctx.toast('还没有备份'); return; }
        await this.restoreFile(files[files.length - 1]);
      } catch (e) {
        console.error('[自动备份] 恢复', e);
        ctx.toast('恢复失败');
      }
    },

    deactivate() {
      if (this._ctx && this._onSave) this._ctx.off('save', this._onSave);
    }
  });
})();

/* 人物关系图插件：从「人物」卡片提取角色名，扫描全书各章正文，
 * 统计同一章内的共现关系，生成可点击跳转的关系图谱。
 * 仅用宿主暴露的 ctx API，不碰任何内部变量。 */
(function () {
  'use strict';

  function escXml(s) {
    return String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  }

  window.MoyePlugins.register({
    id: 'character-graph',
    name: '人物关系图',
    activate(ctx) {
      this._ctx = ctx;
      ctx.ui.addToolbarButton({ label: '人物图', title: '人物关系图谱', onClick: () => this.open() });
    },

    open() {
      const ctx = this._ctx;
      ctx.ui.openModal({
        title: '人物关系图',
        render: (body, close) => {
          this._close = close;
          this.render(body);
        }
      });
    },

    compute() {
      const ctx = this._ctx;
      const book = ctx.getActiveBook();
      if (!book) return { tip: '未打开作品', nodes: [], edges: [] };
      const cards = (book.cards && book.cards.character) || [];
      const names = [];
      const seen = new Set();
      cards.forEach((c) => { const n = (c.name || '').trim(); if (n && !seen.has(n)) { seen.add(n); names.push(n); } });
      if (!names.length) return { tip: '先在右侧资料栏的「人物」卡片里添加角色，再来看关系图。', nodes: [], edges: [] };

      const nodes = names.map((n) => ({ name: n, mentions: 0, chSet: new Set(), firstChId: null }));
      const edgeMap = {};
      book.volumes.forEach((v) => v.chapters.forEach((ch) => {
        const text = ctx.htmlToText(ch.html || '');
        if (!text) return;
        const present = [];
        nodes.forEach((nd, i) => {
          const needle = nd.name;
          let count = 0, k = 0;
          while ((k = text.indexOf(needle, k)) !== -1) { count++; k += needle.length; }
          if (count > 0) {
            nd.mentions += count;
            nd.chSet.add(ch.id);
            if (!nd.firstChId) nd.firstChId = ch.id;
            present.push(i);
          }
        });
        for (let a = 0; a < present.length; a++) {
          for (let b = a + 1; b < present.length; b++) {
            const key = present[a] + '|' + present[b];
            edgeMap[key] = (edgeMap[key] || 0) + 1;
          }
        }
      }));

      const edges = Object.keys(edgeMap).map((key) => {
        const p = key.split('|').map(Number);
        return { a: p[0], b: p[1], w: edgeMap[key] };
      });
      return { tip: null, nodes, edges };
    },

    jump(firstChId, name) {
      const ctx = this._ctx;
      if (firstChId) {
        ctx.selectChapter(firstChId);
        ctx.toast('已跳转到：「' + name + '」首次出场');
      } else {
        ctx.toast('「' + name + '」在正文中还没有出现');
      }
      if (this._close) this._close();
    },

    render(body) {
      const ctx = this._ctx;
      body.innerHTML = '';
      const data = this.compute();

      const head = document.createElement('div');
      head.className = 'tool-row';
      head.style.cssText = 'margin-bottom:8px;justify-content:space-between';
      const recheck = document.createElement('button');
      recheck.className = 'mini-btn';
      recheck.textContent = '重新计算';
      recheck.addEventListener('click', () => this.render(body));
      const hint = document.createElement('span');
      hint.className = 'muted';
      hint.style.cssText = 'font-size:12px';
      hint.textContent = '关系线=同章共现次数（基于「人物」卡片，近似统计）';
      head.appendChild(recheck);
      head.appendChild(hint);
      body.appendChild(head);

      if (data.tip) {
        const tip = document.createElement('div');
        tip.className = 'empty-tip';
        tip.textContent = data.tip;
        body.appendChild(tip);
        return;
      }

      const used = data.nodes.filter((n) => n.mentions > 0).length;
      const stat = document.createElement('div');
      stat.className = 'muted';
      stat.style.cssText = 'font-size:12px;margin-bottom:8px';
      stat.textContent = '共 ' + data.nodes.length + ' 个角色 · 正文出现 ' + used + ' 个 · 关系线 ' + data.edges.length + ' 条';
      body.appendChild(stat);

      // 布局：环形排布
      const W = 620, H = 420, cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 70;
      data.nodes.forEach((n, i) => {
        const a = (i / Math.max(1, data.nodes.length)) * Math.PI * 2 - Math.PI / 2;
        n.x = Math.round(cx + Math.cos(a) * R);
        n.y = Math.round(cy + Math.sin(a) * R);
        n.r = 14 + Math.min(22, Math.sqrt(n.mentions) * 3.5);
      });
      const maxW = data.edges.reduce((m, e) => Math.max(m, e.w), 0) || 1;

      let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" style="max-height:420px;background:var(--panel,#fff);border:1px solid var(--line);border-radius:8px">';
      data.edges.forEach((e) => {
        const A = data.nodes[e.a], B = data.nodes[e.b];
        const op = (0.18 + 0.6 * (e.w / maxW)).toFixed(2);
        const sw = (1 + 3 * (e.w / maxW)).toFixed(1);
        svg += '<line x1="' + A.x + '" y1="' + A.y + '" x2="' + B.x + '" y2="' + B.y + '" stroke="#c9a0dc" stroke-opacity="' + op + '" stroke-width="' + sw + '" />';
      });
      data.nodes.forEach((n, i) => {
        const dim = n.mentions === 0;
        const fill = dim ? '#e6e6e6' : '#f3c6a8';
        const stroke = dim ? '#cfcfcf' : '#d98a5a';
        const label = n.name.length > 8 ? n.name.slice(0, 8) + '…' : n.name;
        svg += '<g class="cg-node" data-ch="' + i + '" style="cursor:pointer">';
        svg += '<circle cx="' + n.x + '" cy="' + n.y + '" r="' + n.r + '" fill="' + fill + '" stroke="' + stroke + '" stroke-width="1.5" />';
        if (n.mentions > 0) svg += '<text x="' + n.x + '" y="' + (n.y + 4) + '" text-anchor="middle" font-size="12" fill="#5a3a22">' + n.mentions + '</text>';
        svg += '<text x="' + n.x + '" y="' + (n.y + n.r + 14) + '" text-anchor="middle" font-size="13" fill="#333">' + escXml(label) + '</text>';
        svg += '</g>';
      });
      svg += '</svg>';

      const svgWrap = document.createElement('div');
      svgWrap.innerHTML = svg;
      body.appendChild(svgWrap);

      const list = document.createElement('div');
      list.style.cssText = 'margin-top:10px';
      data.nodes.slice().sort((a, b) => b.mentions - a.mentions).forEach((n) => {
        const i = data.nodes.indexOf(n);
        const row = document.createElement('div');
        row.className = 'tool-row';
        row.style.cssText = 'justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--line);cursor:pointer';
        row.innerHTML = '<span><b>' + ctx.escapeHtml(n.name) + '</b> <span class="muted" style="font-size:12px">出现 ' + n.mentions + ' 次 · ' + n.chSet.size + ' 章</span></span>' +
          '<button class="mini-btn">跳转</button>';
        row.addEventListener('click', () => this.jump(n.firstChId, n.name));
        list.appendChild(row);
      });
      body.appendChild(list);

      // SVG 节点点击
      Array.prototype.slice.call(body.querySelectorAll('.cg-node')).forEach((g) => {
        g.addEventListener('click', () => {
          const nd = data.nodes[+g.getAttribute('data-ch')];
          this.jump(nd.firstChId, nd.name);
        });
      });
    },

    deactivate() {}
  });
})();

/* 全文搜索插件：在本书全部章节里搜关键词，点结果跳转。
 * 支持「区分大小写」「正则」两个开关。仅用宿主暴露的 ctx API，不碰任何内部变量。 */
(function () {
  'use strict';
  window.MoyePlugins.register({
    id: 'fulltext-search',
    name: '全文搜索',
    activate(ctx) {
      this._ctx = ctx;
      this.caseSensitive = false;
      this.useRegex = false;
      ctx.ui.addToolbarButton({ label: '搜索', title: '跨章节搜索全书', onClick: () => this.open() });
    },
    open() {
      const ctx = this._ctx;
      ctx.ui.openModal({
        title: '全文搜索',
        render: (body) => {
          const input = document.createElement('input');
          input.className = 'fts-input';
          input.placeholder = '输入关键词，即时搜索（全书所有章节）';
          const opts = document.createElement('div');
          opts.className = 'tool-row';
          opts.style.cssText = 'margin-bottom:8px';
          opts.innerHTML =
            '<label class="set-check"><input type="checkbox" id="ftsCase"> 区分大小写</label>' +
            '<label class="set-check"><input type="checkbox" id="ftsRe"> 正则</label>';
          const caseCb = opts.querySelector('#ftsCase');
          const reCb = opts.querySelector('#ftsRe');
          caseCb.checked = this.caseSensitive;
          reCb.checked = this.useRegex;
          caseCb.addEventListener('change', () => { this.caseSensitive = caseCb.checked; run(); });
          reCb.addEventListener('change', () => { this.useRegex = reCb.checked; run(); });

          const count = document.createElement('div');
          count.className = 'fts-count';
          const list = document.createElement('div');
          body.appendChild(input);
          body.appendChild(opts);
          body.appendChild(count);
          body.appendChild(list);

          let timer = null;
          const run = () => {
            const q = input.value.trim();
            if (!q) { count.textContent = ''; list.innerHTML = ''; return; }
            const book = ctx.getActiveBook();
            if (!book) { count.textContent = '未打开作品'; return; }

            let re = null;
            if (this.useRegex) {
              try { re = new RegExp(q, this.caseSensitive ? 'g' : 'gi'); }
              catch (e) { count.textContent = '正则无效：' + e.message; list.innerHTML = ''; return; }
            }
            const ql = this.caseSensitive ? q : q.toLowerCase();

            const hits = [];
            book.volumes.forEach((v) => {
              if (hits.length >= 200) return;
              v.chapters.forEach((c) => {
                if (hits.length >= 200) return;
                const text = ctx.htmlToText(c.html || '');
                if (!text) return;
                if (re) {
                  re.lastIndex = 0; let m;
                  while ((m = re.exec(text)) !== null) {
                    if (m.index === re.lastIndex) re.lastIndex++;
                    if (hits.length >= 200) break;
                    const start = Math.max(0, m.index - 14);
                    const end = Math.min(text.length, m.index + m[0].length + 14);
                    let sn = text.slice(start, end);
                    if (start > 0) sn = '…' + sn;
                    if (end < text.length) sn = sn + '…';
                    hits.push({ chId: c.id, chTitle: c.title || '未命名', vol: v.name, text: sn, hit: m[0] });
                  }
                } else {
                  const tl = this.caseSensitive ? text : text.toLowerCase();
                  let idx = tl.indexOf(ql);
                  while (idx !== -1 && hits.length < 200) {
                    const start = Math.max(0, idx - 14);
                    const end = Math.min(text.length, idx + ql.length + 14);
                    let sn = text.slice(start, end);
                    if (start > 0) sn = '…' + sn;
                    if (end < text.length) sn = sn + '…';
                    hits.push({ chId: c.id, chTitle: c.title || '未命名', vol: v.name, text: sn, hit: ql });
                    idx = tl.indexOf(ql, idx + ql.length);
                  }
                }
              });
            });

            count.textContent = '命中 ' + hits.length + ' 处' + (hits.length >= 200 ? '（仅显示前 200）' : '');
            list.innerHTML = '';
            if (!hits.length) { list.innerHTML = '<div class="empty-tip">没有匹配结果</div>'; return; }
            const escHit = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            hits.forEach((h) => {
              const item = document.createElement('div');
              item.className = 'fts-item';
              const needle = h.hit || q;
              const hl = h.text.replace(new RegExp(escHit(needle), this.caseSensitive ? 'g' : 'gi'), (m) => '<mark>' + m + '</mark>');
              item.innerHTML = '<div class="fts-ch">' + ctx.escapeHtml(h.vol ? h.vol + ' / ' : '') + ctx.escapeHtml(h.chTitle) + '</div>' +
                '<div class="fts-sn">' + hl + '</div>';
              item.addEventListener('click', () => {
                ctx.selectChapter(h.chId);
                ctx.toast('已跳转到：' + h.chTitle);
                const mask = item.closest('.drawer-mask');
                if (mask) mask.click();
              });
              list.appendChild(item);
            });
          };
          input.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(run, 200); });
          input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { clearTimeout(timer); run(); } });
          setTimeout(() => { try { input.focus(); } catch (e) {} }, 30);
        }
      });
    },
    deactivate() {}
  });
})();

/* 文本体检插件：扫描全书或当前章节，检查常见排版/错别字类问题：
 *  - 连续重复标点（3 个及以上相同标点）
 *  - 中文之间多余空格
 *  - 中文之间误用半角标点（应全角）
 *  - 全角标点后多余空格
 *  - 行尾多余空格
 * 结果可点击跳转到对应章节。仅用宿主暴露的 ctx API。 */
(function () {
  'use strict';

  window.MoyePlugins.register({
    id: 'text-lint',
    name: '文本体检',
    activate(ctx) {
      this._ctx = ctx;
      this.scope = 'book';
      ctx.ui.addToolbarButton({ label: '文本体检', title: '错别字与排版体检', onClick: () => this.open() });
    },

    open() {
      const ctx = this._ctx;
      ctx.ui.openModal({
        title: '文本体检',
        render: (body) => { this.render(body); }
      });
    },

    collectChapters() {
      const ctx = this._ctx;
      if (this.scope === 'chapter') {
        const ch = ctx.getActiveChapter();
        return ch ? [ch] : [];
      }
      return ctx.getAllChapters();
    },

    lint(text) {
      const issues = [];
      const lines = text.split('\n');
      lines.forEach((line, li) => {
        // A. 连续重复标点
        let m = line.match(/([，。！？、；：])\1{2,}/);
        if (m) issues.push({ ln: li + 1, msg: '连续重复的标点符号「' + m[1] + '」', snip: line });
        // A2. 省略号过长
        if (/…{4,}/.test(line)) issues.push({ ln: li + 1, msg: '省略号过长（建议一个「…」或「......」）', snip: line });
        // B. 中文之间多余空格
        if (/[一-鿿]\s+[一-鿿]/.test(line)) issues.push({ ln: li + 1, msg: '中文之间有多余空格', snip: line });
        // C. 中文之间半角标点
        if (/[一-鿿][,.!?;:][一-鿿]/.test(line)) issues.push({ ln: li + 1, msg: '中文之间误用半角标点，建议改全角', snip: line });
        // D. 全角标点后空格
        if (/[，。！？、；：]\s/.test(line)) issues.push({ ln: li + 1, msg: '全角标点后有空格', snip: line });
        // E. 行尾空格
        if (/\s+$/.test(line)) issues.push({ ln: li + 1, msg: '行尾有多余空格', snip: line });
      });
      return issues;
    },

    render(body) {
      const ctx = this._ctx;
      body.innerHTML = '';

      const head = document.createElement('div');
      head.className = 'tool-row';
      head.style.cssText = 'margin-bottom:8px;gap:10px;flex-wrap:wrap';

      const scopeSel = document.createElement('select');
      scopeSel.className = 'mini-btn';
      scopeSel.innerHTML = '<option value="book">全书</option><option value="chapter">本章</option>';
      scopeSel.value = this.scope;
      scopeSel.addEventListener('change', () => { this.scope = scopeSel.value; this.render(body); });

      const recheck = document.createElement('button');
      recheck.className = 'mini-btn primary';
      recheck.textContent = '重新体检';
      recheck.addEventListener('click', () => this.render(body));
      head.appendChild(scopeSel);
      head.appendChild(recheck);
      body.appendChild(head);

      const chapters = this.collectChapters();
      if (!chapters.length) {
        const tip = document.createElement('div');
        tip.className = 'empty-tip';
        tip.textContent = this.scope === 'chapter' ? '当前没有选中章节' : '还没有章节';
        body.appendChild(tip);
        return;
      }

      const all = [];
      chapters.forEach((ch) => {
        const text = ctx.htmlToText(ch.html || '');
        if (!text) return;
        const issues = this.lint(text);
        issues.forEach((it) => { all.push({ chId: ch.id, chTitle: ch.title || '未命名', ln: it.ln, msg: it.msg, snip: it.snip }); });
      });

      const stat = document.createElement('div');
      stat.className = 'muted';
      stat.style.cssText = 'font-size:12px;margin-bottom:8px';
      stat.textContent = '范围：' + (this.scope === 'chapter' ? '本章' : '全书 ' + chapters.length + ' 章') + ' · 发现 ' + all.length + ' 处疑似问题';
      body.appendChild(stat);

      if (!all.length) {
        const okEl = document.createElement('div');
        okEl.className = 'empty-tip';
        okEl.textContent = '未发现上述常见排版问题，很干净 ✨';
        body.appendChild(okEl);
        return;
      }

      const cap = 300;
      const shown = all.slice(0, cap);
      const list = document.createElement('div');
      list.style.cssText = 'max-height:320px;overflow:auto';
      shown.forEach((it) => {
        const row = document.createElement('div');
        row.className = 'tool-row';
        row.style.cssText = 'justify-content:space-between;align-items:flex-start;gap:10px;padding:6px 0;border-bottom:1px solid var(--line);cursor:pointer';
        const left = document.createElement('div');
        left.style.cssText = 'min-width:0;flex:1';
        const snip = it.snip.length > 60 ? it.snip.slice(0, 60) + '…' : it.snip;
        left.innerHTML = '<div style="font-size:12px;color:#b34"><b>' + ctx.escapeHtml(it.msg) + '</b></div>' +
          '<div class="muted" style="font-size:12px">' + ctx.escapeHtml(it.chTitle) + ' · 第 ' + it.ln + ' 行</div>' +
          '<div style="font-size:12px;white-space:pre-wrap;word-break:break-all">' + ctx.escapeHtml(snip) + '</div>';
        const btn = document.createElement('button');
        btn.className = 'mini-btn';
        btn.textContent = '跳转';
        row.appendChild(left);
        row.appendChild(btn);
        row.addEventListener('click', () => {
          ctx.selectChapter(it.chId);
          ctx.toast('已跳转到：' + it.chTitle + '（第 ' + it.ln + ' 行附近）');
        });
        list.appendChild(row);
      });
      body.appendChild(list);
      if (all.length > cap) {
        const more = document.createElement('div');
        more.className = 'muted';
        more.style.cssText = 'font-size:12px;margin-top:6px';
        more.textContent = '仅显示前 ' + cap + ' 条，共 ' + all.length + ' 条';
        body.appendChild(more);
      }
    },

    deactivate() {}
  });
})();

/* 写作计时 / 番茄钟插件。
 * - 工具栏「计时」按钮打开面板：开始/暂停/重置，显示本次时长、本次新增字数、平均速度（字/分）。
 * - 监听 save / chapterChange 计算字数增量；番茄钟 25 分钟专注 + 5 分钟休息，到点 toast 提醒。
 * - 每日累计（时长/字数）持久化到 db.plugins，面板显示今日统计。 */
(function () {
  'use strict';

  function bookWords(book) {
    let n = 0;
    if (book && book.volumes) book.volumes.forEach((v) => v.chapters.forEach((c) => { n += (c.words || 0); }));
    return n;
  }
  function fmtDur(ms) {
    const s = Math.max(0, Math.floor(ms / 1000));
    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;
    return (h ? h + ':' : '') + String(m).padStart(h ? 2 : 1, '0') + ':' + String(ss).padStart(2, '0');
  }
  function dateKey(d) { const p = (n) => String(n).padStart(2, '0'); return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()); }

  window.MoyePlugins.register({
    id: 'writing-timer',
    name: '写作计时',
    activate(ctx) {
      this._ctx = ctx;
      const KEY = 'writingTimer.';
      // 运行态
      this.running = false;
      this.startTs = 0;
      this.accMs = 0;          // 已累计专注时长
      this.baseWords = 0;      // 计时开始时的字数
      this.curWords = 0;
      this.tick = null;
      this.pomo = false;
      this.pomoEnd = 0;
      this.pomoPhase = '';
      // 读取今日累计
      const dk = dateKey(new Date());
      this.todayKey = KEY + 'day.' + dk;
      this.today = ctx.getSetting(this.todayKey, { ms: 0, words: 0 });

      this.onSave = () => this.refresh();
      ctx.on('save', this.onSave);
      ctx.on('chapterChange', this.onSave);

      this.curWords = bookWords(ctx.getActiveBook());

      ctx.ui.addToolbarButton({
        label: '计时', title: '写作计时 / 番茄钟',
        onClick: () => this.open()
      });
    },

    snapshotDay() {
      const t = this.today;
      this._ctx.setSetting(this.todayKey, { ms: t.ms, words: t.words });
    },

    totalMs() { return this.accMs + (this.running ? Date.now() - this.startTs : 0); },

    refresh() {
      const ctx = this._ctx;
      const w = bookWords(ctx.getActiveBook());
      this.curWords = w;
      const delta = Math.max(0, w - this.baseWords);
      const ms = this.totalMs();
      const speed = ms > 0 ? Math.round(delta / (ms / 60000)) : 0;
      const el = this._panelEls;
      if (!el) return;
      el.dur.textContent = fmtDur(ms);
      el.add.textContent = '+' + delta + ' 字';
      el.spd.textContent = speed + ' 字/分';
      el.today.textContent = fmtDur(this.today.ms) + ' · +' + this.today.words + ' 字';
    },

    open() {
      const ctx = this._ctx;
      ctx.ui.openModal({
        title: '写作计时',
        render: (body) => {
          const wrap = document.createElement('div');
          wrap.innerHTML =
            '<div style="display:flex;gap:18px;align-items:baseline;margin-bottom:10px">' +
            '<div><div style="font-size:30px;font-weight:700" id="wtDur">00:00</div><div class="muted" style="font-size:12px">本次专注</div></div>' +
            '<div><div style="font-size:18px" id="wtAdd">+0 字</div><div class="muted" style="font-size:12px">本次新增</div></div>' +
            '<div><div style="font-size:18px" id="wtSpd">0 字/分</div><div class="muted" style="font-size:12px">平均速度</div></div>' +
            '</div>' +
            '<div class="tool-row" style="margin-bottom:10px">' +
            '<button class="mini-btn primary" id="wtStart">开始</button>' +
            '<button class="mini-btn" id="wtReset">重置</button>' +
            '<label class="set-check" style="margin-left:8px"><input type="checkbox" id="wtPomo"> 番茄钟 25/5</label>' +
            '</div>' +
            '<div id="wtPomoState" class="muted" style="font-size:12px;min-height:16px;margin-bottom:10px"></div>' +
            '<div class="muted" style="font-size:12px">今日累计：<span id="wtToday">—</span></div>';
          body.appendChild(wrap);
          const dur = wrap.querySelector('#wtDur');
          const add = wrap.querySelector('#wtAdd');
          const spd = wrap.querySelector('#wtSpd');
          const todayEl = wrap.querySelector('#wtToday');
          const pomoState = wrap.querySelector('#wtPomoState');
          this._panelEls = { dur, add, spd, today: todayEl };
          this.refresh();

          const startBtn = wrap.querySelector('#wtStart');
          const resetBtn = wrap.querySelector('#wtReset');
          const pomoCb = wrap.querySelector('#wtPomo');

          startBtn.addEventListener('click', () => {
            if (this.running) {
              // 暂停：结算
              this.accMs += Date.now() - this.startTs;
              this.running = false;
              startBtn.textContent = '开始';
              this.stopPomo();
              pomoState.textContent = '';
              this.settleDay();
            } else {
              this.running = true;
              this.startTs = Date.now();
              this.baseWords = bookWords(ctx.getActiveBook());
              startBtn.textContent = '暂停';
              if (pomoCb.checked) this.startPomo(pomoState);
            }
          });

          resetBtn.addEventListener('click', () => {
            this.running = false; this.accMs = 0; this.startTs = 0;
            this.baseWords = bookWords(ctx.getActiveBook());
            this.stopPomo(); pomoState.textContent = '';
            startBtn.textContent = '开始';
            this.refresh();
          });

          pomoCb.addEventListener('change', () => {
            if (pomoCb.checked && this.running) this.startPomo(pomoState);
            else if (!pomoCb.checked) { this.stopPomo(); pomoState.textContent = ''; }
          });
        }
      });
    },

    startPomo(stateEl) {
      this.pomo = true; this.pomoPhase = 'focus'; this.pomoEnd = Date.now() + 25 * 60 * 1000;
      if (stateEl) stateEl.textContent = '番茄钟：专注中，25 分钟后休息';
      this.pomoTimer = setInterval(() => {
        const left = this.pomoEnd - Date.now();
        if (left <= 0) {
          if (this.pomoPhase === 'focus') {
            this._ctx.toast('专注结束，休息 5 分钟 ☕');
            this.pomoPhase = 'break'; this.pomoEnd = Date.now() + 5 * 60 * 1000;
            if (stateEl) stateEl.textContent = '番茄钟：休息中，5 分钟后继续';
          } else {
            this._ctx.toast('休息结束，继续写吧 ✍️');
            this.pomoPhase = 'focus'; this.pomoEnd = Date.now() + 25 * 60 * 1000;
            if (stateEl) stateEl.textContent = '番茄钟：专注中，25 分钟后休息';
          }
        }
      }, 1000);
    },
    stopPomo() {
      this.pomo = false;
      if (this.pomoTimer) { clearInterval(this.pomoTimer); this.pomoTimer = null; }
    },

    settleDay() {
      const delta = Math.max(0, this.curWords - this.baseWords);
      this.today.ms += this.accMs;
      this.today.words += delta;
      this.snapshotDay();
    },

    deactivate() {
      if (this.running) this.settleDay();
      this.stopPomo();
      if (this._ctx && this.onSave) this._ctx.off('save', this.onSave);
      if (this._ctx && this.onSave) this._ctx.off('chapterChange', this.onSave);
    }
  });
})();
